Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.
  Variables MX CX : Z.

Local Ltac open_static STAT :=
  let PU := fresh "PU" in
  pose proof STAT as (PU & RCR & RN & SPB & PB & EB & BHI & TP & MXLE & CXLE); pose proof PU as PU0;
  destruct PU as (N1 & LO & IMG & CEIL & QLO & QHI & PLO & PHI & ELO & EHI & DPE & AL16);
  unfold PUT_STACK, IPF_STACK, IPF_FRAME, OTF_STACK, INS_STACK, ROPNEW_STACK, RMALLOC_STACK in LO.

(* [comment removed for export] *)
Lemma block_disjoint_client2 : forall s L1 p A n L2 m SP a k,
  hs_RHEAP H s (L1 ++ (p, A, n) :: L2) m -> rclient_range L2 SP a k -> hceil <= SP -> 0 <= k ->
  a + k <= A \/ A + n <= a.
Proof.
  intros s L1 p A n L2 m SP a k HP HR CE Hk.
  assert (INp : In (p, A, n) (L1 ++ (p, A, n) :: L2)) by (apply in_or_app; right; left; reflexivity).
  pose proof (hh_blocks H HH _ _ _ (p, A, n) HP INp) as (R1 & R2 & R3 & R4 & R5). cbn in R1, R2, R3, R4, R5.
  destruct HR as [K|[K|(b & Hb & K1 & K2)]].
  - right. lia.
  - destruct K as (Ka & Kn & _). hcb. lia.
  - pose proof (hh_nodup H HH _ _ _ HP) as ND. rewrite map_app in ND. cbn in ND.
    apply NoDup_app_remove_l in ND. inversion ND; subst.
    assert (NE : blk_id (p, A, n) <> blk_id b).
    { cbn. intros EQ. apply H2. apply in_map_iff. exists b. split; [symmetry; exact EQ| exact Hb]. }
    destruct (hh_disj H HH _ _ _ (p, A, n) b HP INp ltac:(apply in_or_app; right; right; exact Hb) NE) as [D|D]; cbn in D; lia.
Qed.

(* [comment removed for export] *)
Lemma elem_client : forall m Fa S L ns ls em LB SP e,
  FieldsC m Fa S L ns ls em -> FieldsOwn LB em -> e ∈ L -> rclient_range LB SP e 48.
Proof.
  intros m Fa S L ns ls em LB SP e FC OWN He.
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & _).
  destruct (proj1 (LEQ e) He) as [d Ld]. destruct (OWN e d Ld) as [p [IN _]]. pose proof (esize_ge d).
  right; right. exists (p, e, esize d). split; [exact IN | cbn; lia].
Qed.

Lemma body_client : forall m b es insz LB SP x s,
  MBuf m b es insz -> MBufOwn LB es -> In (x, s) es -> rclient_range LB SP x (24 + s).
Proof.
  intros m b es insz LB SP x s MB MOWN IN.
  destruct (MOWN x s IN) as [p INb]. pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ.
  pose proof (mb_block_size_range s ltac:(lia)) as [BR _].
  right; right. exists (p, x, mb_block_size s). split; [exact INb | cbn; lia].
Qed.
