Lemma req_res_facts : forall s LB mbs tbs verb ver h' LB' m SP,
  req_res LB mbs tbs verb ver h' LB' m -> hs_RHEAP H s LB' m -> hceil <= SP -> 1 <= Z.of_nat (length mbs) ->
  Z.of_nat (length mbs) < 2^62 -> Z.of_nat (length tbs) < 2^62 ->
  exists NB, LB' = NB ++ LB /\ lb_bytes NB <= Z.of_nat (length mbs) + Z.of_nat (length tbs) + 1 /\ Z.of_nat (length NB) <= 2
    /\ HdrOwnP LB' h' /\ hv_ver h' = ver /\ 0 <= hv_vb h' < 2^32
    /\ hv_tl h' <> 0 /\ blk_fresh LB SP (hv_tp h') (hv_tl h')
    /\ (hv_ml h' <> 0 -> blk_fresh LB SP (hv_mp h') (hv_ml h') /\ (hv_mp h' + hv_ml h' <= hv_tp h' \/ hv_tp h' + hv_tl h' <= hv_mp h'))
    /\ (forall b, In b NB -> svownedP (hv_mp h') (hv_ml h') b \/ svownedP (hv_tp h') (hv_tl h') b).
