Lemma PfTab_xpresX : forall LB SP X m m', xpres LB SP X m m' -> PfTab m ->
  Forall (fun iv : Z * Z => PF_TABPTR + 8 <= fst iv \/ snd iv <= PF_TABPTR) X -> PfTab m'.
Proof.
  intros LB SP X m m' XP T FX. unfold PfTab in *. eapply xpres_rw_cells; [exact XP | exact T |]. split; [| exact FX].
  right; left. unfold PF_TABPTR, RLIBC, RCTX, RERRNO, RSSP_GUARD, RGOT_SSP, RVMLOCK. cbn. lia.
Qed.

